mapper.select:
SELECT * FROM messages
WHERE conversation_id = #{conversationId}
ORDER BY created_at DESC, id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM messages
WHERE conversation_id = #{conversationId}
  AND type = #{type}
  AND content = #{content}

mapper.update:
UPDATE messages
SET read_at = #{readAt}
WHERE conversation_id = #{conversationId}
  AND read_at IS NULL

UPDATE messages
SET read_at = #{readAt}
WHERE read_at IS NULL
  AND conversation_id IN (
    SELECT id FROM conversations WHERE owner_id = #{ownerId}
  )
